import re, html as H, json

raw = open('/tmp/nas_takeover/nominative2.html').read()
body = raw[raw.find('<body'):]

cards = re.findall(r'<div class="search-item" data-id="(\d+)">(.*?)(?=<div class="search-item"|</ul>\s*<!--|<nav class="pagination|$)', body, re.S)
print('cards:', len(cards))

def clean(t):
    t = re.sub(r'<[^>]+>', ' ', t)
    return re.sub(r'\s+', ' ', H.unescape(t)).strip()

results = []
for cid, chunk in cards:
    rec = {'s_id': cid}
    m = re.search(r'<h3[^>]*>\s*<a href="/detail-nominative/\?s_id=(\d+)"[^>]*>(.*?)</a>', chunk, re.S)
    if m:
        rec['name'] = clean(m.group(2))
    # vitals lines like "Nascita: Viadana , 1789"
    for label, key in [('Nascita','birth'),('Morte','death'),('Matrimonio','marriage')]:
