cd /tmp/nas_takeover && cat > parse.py << 'EOF'
import re, html as H, sys, json

def clean(t):
    t = re.sub(r'<[^>]+>', ' ', t)
    return re.sub(r'\s+', ' ', H.unescape(t)).strip()

def parse_search(path):
    raw = open(path).read()
    body = raw[raw.find('<body'):]
    cards = re.findall(r'<div class="search-item" data-id="(\d+)">(.*?)(?=<div class="search-item"|</ul>\s*<nav|<nav class="pagination|$)', body, re.S)
    out = []
    for cid, chunk in cards:
        rec = {'s_id': cid}
        m = re.search(r'<h3[^>]*>\s*<a href="/detail-nominative/\?s_id=(\d+)"[^>]*>(.*?)</a>', chunk, re.S)
        if m: rec['name'] = clean(m.group(2))
        for label, key in [('Nascita','birth'),('Morte','death'),('Matrimonio','marriage')]:
            m = re.search(label + r':\s*.{0,10}?([^<]{3,90})</', chunk, re.S)
            if m: rec[key] = clean(m.group(1))
        rels = re.findall(r'<h4 class="no-margin-bottom">([^<]+)</h4>\s*<a href="/detail-nominative/\?s_id=(\d+)"[^>]*>(.*?)</a>', chunk, re.S)
        for rel, rsid, rname in rels:
            rec.setdefault('rel', []).append(f"{clean(rel)}: {clean(rname)}")
        acts = re.findall(r'<a href="(/ark:/12657/[^"]+)"[^>]*>\s*<strong>([^<]+)</strong>\s*<br>\s*([^<]+)</a>', chunk, re.S)
        for ark, atype, adate in acts:
            rec.setdefault('acts', []).append(f"{clean(atype)} {clean(adate)} [https://antenati.cultura.gov.it{ark}]")
        out.append(rec)
    return out

if __name__ == '__main__':
    for path in sys.argv[1:]:
        recs = parse_search(path)
        print(f"=== {path}: {len(recs)} records ===")
        for r in recs:
            print(json.dumps(r, ensure_ascii=False))
        print()
