// FS bot phase driver - persistent profile, headed system Chrome
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const PROFILE = '/Users/renzof/Documents/GitHub/GH/NAS/FamilyTree/.fs-profile';
const OUT = '/tmp/nas_takeover/fsbot/out';
fs.mkdirSync(OUT, { recursive: true });
fs.mkdirSync(PROFILE, { recursive: true });

const phase = process.argv[2] || 'help';

async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function isLoggedIn(ctx) {
  const cookies = await ctx.cookies('https://www.familysearch.org');
  return cookies.some(c => c.name === 'fssessionid' && c.value && c.value.length > 5);
}

async function launch() {
  const ctx = await chromium.launchPersistentContext(PROFILE, {
    channel: 'chrome',
    headless: false,
    viewport: null,
    args: ['--window-size=1500,950', '--lang=en-US'],
    slowMo: 400, // human-like pace
  });
  return ctx;
}

async function waitLogin(ctx, page, maxMs = 15 * 60 * 1000) {
  if (await isLoggedIn(ctx)) return true;
  await page.goto('https://www.familysearch.org/', { waitUntil: 'domcontentloaded' }).catch(() => {});
  const t0 = Date.now();
  while (Date.now() - t0 < maxMs) {
    if (await isLoggedIn(ctx)) return true;
    await sleep(3000);
  }
  return false;
}

async function dumpPerson(page, pid, label) {
  const url = `https://www.familysearch.org/tree/person/details/${pid}`;
  await page.goto(url, { waitUntil: 'domcontentloaded' });
  await sleep(6000); // let the SPA render
  await page.screenshot({ path: path.join(OUT, `${label}-top.png`) });
  const text = await page.evaluate(() => document.body.innerText);
  fs.writeFileSync(path.join(OUT, `${label}-page.txt`), text);
  // full-page screenshot for sources/family sections
  await page.screenshot({ path: path.join(OUT, `${label}-full.png`), fullPage: true });
  return text;
}

async function main() {
  if (phase === 'p0') {
    const ctx = await launch();
    const page = ctx.pages()[0] || await ctx.newPage();
    const ok = await waitLogin(ctx, page);
    if (!ok) { console.log('LOGIN_TIMEOUT'); await ctx.close(); process.exit(2); }
    console.log('LOGGED_IN');
    const regina = await dumpPerson(page, 'PNTV-S6Q', 'regina');
    console.log('REGINA_DUMPED len=' + regina.length);
    await sleep(4000);
    const cesare = await dumpPerson(page, 'PNTJ-HR3', 'cesare');
    console.log('CESARE_DUMPED len=' + cesare.length);
    console.log('P0_DONE');
    await ctx.close();
    process.exit(0);
  }
  console.log('UNKNOWN_PHASE ' + phase);
  process.exit(1);
}

main().catch(e => { console.error('FATAL', e.message); process.exit(3); });

