// Drive the user's real Dia browser over CDP. NEVER closes the browser.
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const OUT = '/tmp/nas_takeover/fsbot/out';
fs.mkdirSync(OUT, { recursive: true });
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function main() {
  const phase = process.argv[2] || 'p0';
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 350 });
  const ctx = browser.contexts()[0];
  if (!ctx) { console.log('NO_CONTEXT'); process.exit(2); }

  // find an existing familysearch tab, else open one
  let page = ctx.pages().find(p => /familysearch\.org/.test(p.url()));
  if (!page) {
    page = await ctx.newPage();
    await page.goto('https://www.familysearch.org/en/', { waitUntil: 'domcontentloaded' }).catch(e => console.log('nav err', e.message));
  }
  console.log('TAB_URL:', page.url().slice(0, 120));

  const cookies = await ctx.cookies('https://www.familysearch.org');
  const loggedIn = cookies.some(c => c.name === 'fssessionid' && c.value.length > 5);
  console.log('LOGGED_IN:', loggedIn);
  if (!loggedIn) { console.log('NEED_LOGIN (in Dia)'); process.exit(3); }

  async function dumpPerson(pid, label) {
    const url = `https://www.familysearch.org/tree/person/details/${pid}`;
    await page.goto(url, { waitUntil: 'domcontentloaded' });
    await sleep(9000); // SPA render
    const text = await page.evaluate(() => document.body.innerText);
    fs.writeFileSync(path.join(OUT, `${label}-page.txt`), text);
    await page.screenshot({ path: path.join(OUT, `${label}-top.png`) });
    await page.screenshot({ path: path.join(OUT, `${label}-full.png`), fullPage: true });
    console.log(`DUMPED ${pid} (${label}): ${text.length} chars`);
    return text;
  }

  if (phase === 'p0') {
    await dumpPerson('PNTV-S6Q', 'regina');
    await sleep(3000);
    await dumpPerson('PNTJ-HR3', 'cesare');
    // also grab Leopoldo GVVT-YWQ to find Rosa Galafassi's PID
    await sleep(3000);
    const leo = await dumpPerson('GVVT-YWQ', 'leopoldo');
    const m = leo.match(/Rosa[^()\n]*Galafassi|Galafassi,?\s+Rosa/i);
    console.log('ROSA_NAME_SEEN:', !!m);
    console.log('P0_DONE');
  }
  await browser.close(); // disconnects CDP only, Dia stays open
  process.exit(0);
}
main().catch(e => { console.error('FATAL', e.message); process.exit(1); });

