const { chromium } = require('playwright');
const sleep = ms => new Promise(r => setTimeout(r, ms));
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 250 });
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => /antenati/.test(p.url()));
  await page.bringToFront();
  // find manifest link on the page
  const manifestUrl = await page.evaluate(async () => {
    // try the known ark manifest endpoint
    const links = [...document.querySelectorAll('a')].map(a => a.href).filter(h => /manifest|iiif/i.test(h));
    // also try common json sidecar in page source
    const html = document.documentElement.innerHTML;
    const m = html.match(/https:\/\/[^"']+manifest[^"']*/i);
    return { links, m: m ? m[0] : null };
  });
  console.log('manifest candidates:', JSON.stringify(manifestUrl).slice(0, 500));
  // Antenati ark manifests usually at /iiif/ark:.../manifest or from metafad. Try fetch pattern used by mirador config
  const tryUrls = manifestUrl.links.concat(manifestUrl.m ? [manifestUrl.m] : []);
  let manifest = null, usedUrl = null;
  for (const u of tryUrls) {
    try {
      const r = await page.evaluate(async (url) => { const res = await fetch(url); return { status: res.status, body: await res.text() }; }, u);
      if (r.status === 200 && r.body.includes('canvas')) { manifest = JSON.parse(r.body); usedUrl = u; break; }
    } catch (e) {}
  }
  if (!manifest) {
    // guess: mirador config embedded in page source
    const guess = await page.evaluate(() => {
      const html = document.documentElement.innerHTML;
      const m = html.match(/https:\/\/[^"']+\/iiif\/[^"']+/i);
      return m ? m[0] : null;
    });
    console.log('guess:', guess);
    if (guess) {
      const r = await page.evaluate(async (url) => { const res = await fetch(url); return { status: res.status, body: await res.text() }; }, guess);
      if (r.status === 200) { manifest = JSON.parse(r.body); usedUrl = guess; }
    }
  }
  if (!manifest) { console.log('NO_MANIFEST'); process.exit(2); }
  console.log('MANIFEST:', usedUrl, 'canvases:', manifest.sequences[0].canvases.length);
  const canvas = manifest.sequences[0].canvases[11]; // page 12 of 79
  const svc = canvas.images[0].resource.service['@id'] || canvas.images[0].resource['@id'];
  console.log('IMAGE SERVICE:', svc);
  const width = canvas.width, height = canvas.height;
  console.log('canvas size:', width, height);
  // groom description ~ right page, 50-75% height, 35-75% width
  const x = Math.round(width * 0.35), y = Math.round(height * 0.50);
  const w = Math.round(width * 0.40), h = Math.round(height * 0.28);
  const regionUrl = `${svc}/pct:${(x/width*100).toFixed(1)},${(y/height*100).toFixed(1)},${(w/width*100).toFixed(1)},${(h/height*100).toFixed(1)}/2400,/0/default.jpg`;
  console.log('REGION URL:', regionUrl);
  const p2 = await ctx.newPage();
  await p2.goto(regionUrl, { waitUntil: 'load', timeout: 60000 });
  await sleep(2500);
  await p2.screenshot({ path: '/tmp/nas_takeover/fsbot/out/groom-region.png' });
  console.log('SAVED groom-region.png');
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 400)); process.exit(1); });

