    const els = [...document.querySelectorAll('textarea, [contenteditable="true"]')].filter(e => e.getBoundingClientRect().width > 0);
    if (!els.length) return false;
    const el = els[els.length - 1];
    el.focus();
    return true;
  });
  console.log('reason field focused:', filled);
  if (filled) {
    const reason = 'WRONG PARENT - this relationship was created in error. The Antenati birth-index entry for Regina Toschi b 17 Jun 1876 San Matteo delle Chiaviche (nominativo s_id 37522506) names father CESARE TOSCHI + mother ARTEMISIA BONESI - that is the CESARE TOSCHI BORN 1852 (PCZG-LS6, son of Angelo Toschi + Teresa Bortolotti), who married Maria Artemisia Filomena Bonesi in Dosolo on 2 Mar 1873 (act an_ud36642060: groom "celibe, di anni ventun", born Correggioverde, parents resident in Dosolo). THIS Cesare (PNTJ-HR3, b about 1839, father of Elvira b 1871 + Rosina b 1871 by first wife Rosina) would have been about 37 and a widower in 1876, not "celibe" aged 21. Regina is already correctly placed under PCZG-LS6 + PCZG-5Z7 (see PCZP-K6D); this profile PNTV-S6Q will be merged into it.';
    await page.keyboard.type(reason, { delay: 2 });
  }
  await sleep(600);
  // DELETE button (bottom of dialog)
  const del = page.getByRole('button', { name: /^DELETE$/i }).last();
  await del.scrollIntoViewIfNeeded().catch(() => {});
  await sleep(400);
  await page.screenshot({ path: '/tmp/nas_takeover/fsbot/out/regina-delete-reason.png' });
  await del.click();
  console.log('DELETE_CLICKED');
