  if (!page) { console.log('MERGE TAB GONE'); process.exit(2); }
  // right-panel checkboxes at x~1443: Name (already true), Birth (false -> check)
  const panel = await page.evaluate(() => {
    const out = [];
    document.querySelectorAll('input[type="checkbox"]').forEach(el => {
      const r = el.getBoundingClientRect();
      if (r.width > 0 && r.x > 1400) out.push({ label: el.getAttribute('aria-label') || (el.closest('label') ? el.closest('label').innerText.trim() : ''), checked: el.checked, y: Math.round(r.y) });
    });
    return out;
  });
  console.log('PANEL BOXES:', JSON.stringify(panel));
  const birthBox = panel.find(b => b.label === 'Birth');
  if (birthBox && !birthBox.checked) {
    await page.mouse.click(1443 + 8, birthBox.y + 8);
    await sleep(800);
  }
  // reason statement: the textarea/contenteditable near the panel
  const typed = await page.evaluate(() => {
    const els = [...document.querySelectorAll('textarea, [contenteditable="true"]')].filter(e => e.getBoundingClientRect().width > 0);
    const el = els[els.length - 1];
    if (!el) return false;
    el.focus();
    el.click && el.click();
    return true;
  });
  console.log('reason focused:', typed);
  if (typed) {
    await page.keyboard.type('Same person: both profiles are Regina Toschi born 17 June 1876 at San Matteo delle Chiaviche (frazione di Viadana), daughter of Cesare Toschi and Artemisia Bonesi (married at Dosolo 2 Mar 1873, act an_ud36642060). Birth register: Archivio di Stato di Mantova, Nati 1876 San Matteo delle Chiaviche, act already attached to PNTV-S6Q. PNTV-S6Q was created in error with the wrong father (Cesare b about 1839); the correct father is Cesare Toschi b 1852 (PCZG-LS6), already on the surviving profile. Merging the duplicate into PCZP-K6D.', { delay: 1 });
    await sleep(800);
  }
  // "I have reviewed this merge." checkbox
  const reviewed = await page.evaluate(() => {
    const els = [...document.querySelectorAll('input[type="checkbox"]')].filter(e => e.getBoundingClientRect().width > 0 && e.getBoundingClientRect().x > 1400);
    const el = els[els.length - 1];
    if (!el || el.checked) return el ? 'already' : 'missing';
    el.click();
    return 'clicked';
  });
  console.log('reviewed checkbox:', reviewed);
  await sleep(1000);
  await page.screenshot({ path: '/tmp/nas_takeover/fsbot/out/merge-wiz-s7.png', fullPage: true });
  // MERGE button state
  const st = await page.evaluate(() => {
    const els = [...document.querySelectorAll('button')].filter(b => /^merge$/i.test((b.innerText || '').trim()) && b.getBoundingClientRect().width > 0);
    return els.map(b => ({ disabled: b.disabled || b.getAttribute('aria-disabled') === 'true' }));
  });
  console.log('MERGE buttons:', JSON.stringify(st));
