// Phase A: find San Matteo Morti + Matrimoni register series via in-page fetch, save results
const { chromium } = require('playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 200 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /antenati\.cultura\.gov\.it/.test(p.url()));
  if (!page) {
    page = await ctx.newPage();
    await page.goto('https://antenati.cultura.gov.it/', { waitUntil: 'load', timeout: 60000 }).catch(e => console.log('nav:', e.message.slice(0, 80)));
    await sleep(5000);
  }
  console.log('tab:', page.url().slice(0, 80));
  const results = {};
  for (const [label, url] of [
    ['morti', 'https://antenati.cultura.gov.it/search-registry/?localita=San+Matteo+delle+Chiaviche&tipologia=Morti&lang=it'],
    ['matrimoni', 'https://antenati.cultura.gov.it/search-registry/?localita=San+Matteo+delle+Chiaviche&tipologia=Matrimoni&lang=it'],
    ['matrimoni_pubbl', 'https://antenati.cultura.gov.it/search-registry/?localita=San+Matteo+delle+Chiaviche&tipologia=Matrimoni+pubblicazioni+e+opposizioni&lang=it'],
  ]) {
    const res = await page.evaluate(async (u) => {
      const r = await fetch(u, { credentials: 'include' });
      return { status: r.status, body: await r.text() };
    }, url);
    console.log(label, res.status, 'len', res.body.length);
    const series = await page.evaluate((html) => {
      const doc = new DOMParser().parseFromString(html, 'text/html');
      const out = [];
      doc.querySelectorAll('a[href*="serie="]').forEach(a => {
        const t = (a.innerText || '').replace(/\s+/g, ' ').trim();
        if (t) out.push({ text: t.slice(0, 140), href: a.href });
      });
      // also grab raw card text if structure differs
      if (!out.length) {
        const body = doc.body.innerText.replace(/\n+/g, ' | ');
        out.push({ fallback: body.slice(0, 1500) });
      }
      return out;
    }, res.body);
    results[label] = series;
  }
  fs.writeFileSync(`${OUT}/sanmatteo-series.json`, JSON.stringify(results, null, 1));
  console.log(JSON.stringify(results, null, 1).slice(0, 4000));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

