// Open Morti indice registers in Dia tabs and photograph the T pages
// Start with 1872 (an_ua2053806). The annual index is alphabetical.
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 200 });
  const ctx = browser.contexts()[0];
  const page = await ctx.newPage();
  await page.goto('https://antenati.cultura.gov.it/ark:/12657/an_ua2053806', { waitUntil: 'load', timeout: 60000 });
  await sleep(10000); // mirador load
  console.log('TITLE:', await page.title());
  await page.screenshot({ path: `${OUT}/morti-indice-1872-p1.png` });
  // get page count + manifest info
  const info = await page.evaluate(() => {
    const t = document.body.innerText;
    const m = t.match(/(\d+) di (\d+)/);
    const breadcrumb = (t.match(/Stato civile[^>]*San Matteo[^>]*/i) || [''])[0];
    return { pager: m ? m[0] : 'none', breadcrumb: breadcrumb.slice(0, 100) };
  });
  console.log('INFO:', JSON.stringify(info));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

// Flip through the 1872 Morti indice and photograph every page (24 pages, small register)
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 150 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /an_ua2053806/.test(p.url()));
  if (!page) { console.log('TAB GONE'); process.exit(2); }
  await page.bringToFront();
  // next-image button = "Prossimo oggetto"
  const shots = [];
  for (let p = 1; p <= 24; p++) {
    // wait for image render
    await sleep(3500);
    // read pager
    const pager = await page.evaluate(() => {
      const m = document.body.innerText.match(/(\d+) di (\d+)/);
      return m ? `${m[1]}/${m[2]}` : '?';
    });
    const f = `${OUT}/mi1872-p${String(p).padStart(2, '0')}.png`;
    await page.screenshot({ path: f });
    shots.push(f);
    console.log('shot', pager);
    if (p < 24) {
      await page.evaluate(() => {
        const b = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        if (b) b.click();
      });
      await sleep(2500);
    }
  }
  fs.writeFileSync(`${OUT}/mi1872-shots.json`, JSON.stringify(shots, null, 1));
  console.log('DONE', shots.length);
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

// Identify which screenshots are valid (image content) vs error pages
// by checking pixel variance cheaply: decode PNG size + look at unique bytes
const fs = require('fs');
const { execSync } = require('child_process');
const files = fs.readdirSync('/tmp/nas_takeover/fsbot/out').filter(f => /^mi1872-p\d+\.png$/.test(f)).sort();
const sizes = files.map(f => {
  const st = fs.statSync('/tmp/nas_takeover/fsbot/out/' + f);
  return { f, kb: Math.round(st.size / 1024) };
});
sizes.forEach(s => console.log(s.f, s.kb + 'KB'));

// Patient index walker: reload page until image loads (detect via PNG size), pace 15s+
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 150 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /an_ua2053806/.test(p.url()));
  if (!page) {
    page = await ctx.newPage();
    await page.goto('https://antenati.cultura.gov.it/ark:/12657/an_ua2053806', { waitUntil: 'load', timeout: 60000 });
    await sleep(9000);
  }
  await page.bringToFront();

  const shotValid = (f) => { try { return fs.statSync(f).size > 300000; } catch (e) { return false; } };

  for (let p = 7; p <= 24; p++) {
    const f = `${OUT}/mi1872-p${String(p).padStart(2, '0')}.png`;
    // navigate to page p via pager input? Use next-clicks; simpler: reload to current pos each time is slow.
    // Click next until pager shows p/24
    for (let tries = 0; tries < 6; tries++) {
      // dismiss any error dialog
      await page.evaluate(() => {
        const b = [...document.querySelectorAll('button')].find(x => /^ok$/i.test((x.innerText || '').trim()));
        if (b) b.click();
      });
      await sleep(1200);
      const cur = await page.evaluate(() => {
        const m = document.body.innerText.match(/(\d+) di 24/);
        return m ? parseInt(m[1]) : 0;
      });
      if (cur === p) break;
      await page.evaluate(() => {
        const b = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        if (b) b.click();
      });
      await sleep(4000);
    }
    await sleep(6000); // let image load
    await page.screenshot({ path: f });
    let ok = shotValid(f);
    let attempts = 1;
    while (!ok && attempts <= 4) {
      console.log(`p${p}: blank (attempt ${attempts}), waiting 20s and reloading view...`);
      await sleep(20000);
      // nudge reload of image: click prev then next
      await page.evaluate(() => {
        const b1 = [...document.querySelectorAll('button')].find(x => /previous item/i.test(x.title || ''));
        const b2 = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        if (b1) b1.click();
      });
      await sleep(5000);
      await page.evaluate(() => {
        const b2 = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        if (b2) b2.click();
      });
      await sleep(8000);
      await page.screenshot({ path: f });
      ok = shotValid(f);
      attempts++;
    }
    console.log(`p${p}: ${ok ? 'OK' : 'STILL BLANK'} (${attempts} attempts)`);
    await sleep(9000); // pacing
  }
  console.log('DONE');
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

