// Patient register walker: open ark, jump to page range, screenshot with retry on throttle
// usage: node regwalk.js <ark> <fromPage> <toPage> <labelPrefix>
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';

const ark = process.argv[2];
const from = parseInt(process.argv[3] || '1');
const to = parseInt(process.argv[4] || '1');
const prefix = process.argv[5] || 'reg';

(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 120 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /antenati/.test(p.url()));
  if (!page) {
    page = await ctx.newPage();
    await page.goto(`https://antenati.cultura.gov.it/ark:/12657/${ark}`, { waitUntil: 'load', timeout: 60000 });
    await sleep(10000);
  } else {
    await page.goto(`https://antenati.cultura.gov.it/ark:/12657/${ark}`, { waitUntil: 'load', timeout: 60000 });
    await sleep(10000);
  }
  await page.bringToFront();

  const total = await page.evaluate(() => {
    const m = document.body.innerText.match(/(\d+) di (\d+)/);
    return m ? parseInt(m[2]) : 0;
  });
  console.log(`${prefix}: ${total} pages total`);
  if (!total) { console.log('NO PAGER - aborting'); process.exit(2); }

  const shotValid = (f) => { try { return fs.statSync(f).size > 300000; } catch (e) { return false; } };
  const results = [];

  for (let p = from; p <= Math.min(to, total); p++) {
    const f = `${OUT}/${prefix}-p${String(p).padStart(2, '0')}.png`;
    if (shotValid(f)) { console.log(`p${p}: already have`); continue; }
    // navigate to page p: click next/prev until pager matches
    let cur = await page.evaluate(() => {
      const m = document.body.innerText.match(/(\d+) di (\d+)/);
      return m ? parseInt(m[1]) : 0;
    });
    let guard = 0;
    while (cur !== p && guard < 30) {
      const ok = await page.evaluate(({ target }) => {
        const dismiss = [...document.querySelectorAll('button')].find(x => /^ok$/i.test((x.innerText || '').trim()));
        if (dismiss) { dismiss.click(); return false; }
        const next = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        const prev = [...document.querySelectorAll('button')].find(x => /previous item/i.test(x.title || ''));
        const m = document.body.innerText.match(/(\d+) di (\d+)/);
        const c = m ? parseInt(m[1]) : 0;
        if (c < target && next) { next.click(); return true; }
        if (c > target && prev) { prev.click(); return true; }
        return c === target;
      }, { target: p });
      await sleep(3500);
      cur = await page.evaluate(() => {
        const m = document.body.innerText.match(/(\d+) di (\d+)/);
        return m ? parseInt(m[1]) : 0;
      });
      guard++;
      if (!ok && guard > 6) await sleep(8000);
    }
    await sleep(7000);
    await page.screenshot({ path: f });
    let ok = shotValid(f);
    let attempts = 1;
    while (!ok && attempts <= 5) {
      console.log(`p${p}: throttled, waiting 25s (attempt ${attempts})`);
      await sleep(25000);
      // reload the page view via prev+next nudge
      await page.evaluate(() => {
        const b1 = [...document.querySelectorAll('button')].find(x => /previous item/i.test(x.title || ''));
        if (b1) b1.click();
      });
      await sleep(6000);
      await page.evaluate(() => {
        const b2 = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        if (b2) b2.click();
      });
      await sleep(9000);
      await page.screenshot({ path: f });
      ok = shotValid(f);
      attempts++;
    }
    results.push({ p, ok });
    console.log(`p${p}: ${ok ? 'OK' : 'BLANK'}`);
    await sleep(10000);
  }
  fs.writeFileSync(`${OUT}/${prefix}-results.json`, JSON.stringify(results, null, 1));
  console.log('DONE', JSON.stringify(results));
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 200)); process.exit(1); });

