const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 250 });
  const ctx = browser.contexts()[0];
  const page = await ctx.newPage();
  await page.goto('https://www.familysearch.org/en/search/image/index?owc=https://www.familysearch.org/service/cds/recapi/collections/1934580/waypoints', { waitUntil: 'load', timeout: 60000 });
  for (let i = 1; i <= 14; i++) { await sleep(4000); const l = await page.evaluate(() => document.body.innerText.length).catch(() => 0); if (l > 1500) break; }
  await sleep(2500);
  const t = await page.evaluate(() => document.body.innerText);
  fs.writeFileSync(`${OUT}/fs-img-browse.txt`, t);
  console.log('TITLE:', await page.title());
  // find waypoint links containing Viadana
  const wps = await page.evaluate(() => {
    const out = [];
    document.querySelectorAll('a').forEach(a => {
      const tt = (a.innerText || '').trim();
      if (/viadana|mantova/i.test(tt) && tt.length < 120) out.push({ t: tt, h: a.href.slice(0, 180) });
    });
    return out.slice(0, 25);
  });
  console.log('WAYPOINTS:', JSON.stringify(wps, null, 1));
  await page.screenshot({ path: `${OUT}/fs-img-browse.png`, fullPage: true });
  await page.close();
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

