const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
const URL1 = 'https://www.familysearch.org/en/search/image/index?owc=74BJ-RXW%3A1484559902%3Fcc%3D1934580&cc=1934580';
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 250 });
  const ctx = browser.contexts()[0];
  const page = await ctx.newPage();
  await page.goto(URL1, { waitUntil: 'load', timeout: 60000 });
  for (let i = 1; i <= 14; i++) { await sleep(4000); const l = await page.evaluate(() => document.body.innerText.length).catch(() => 0); if (l > 1200) break; }
  await sleep(2500);
  const t = await page.evaluate(() => document.body.innerText);
  fs.writeFileSync(`${OUT}/fs-sm-waypoints.txt`, t);
  console.log('TITLE:', await page.title());
  const wps = await page.evaluate(() => {
    const out = [];
    document.querySelectorAll('a').forEach(a => {
      const h = a.href || '';
      const tt = (a.innerText || '').trim();
      if (/morti|matrimoni|nati/i.test(tt) && tt.length < 90 && h.includes('image')) out.push({ t: tt, h: h.slice(0, 190) });
    });
    return out.slice(0, 40);
  });
  console.log('REGISTERS:', JSON.stringify(wps, null, 1));
  await page.screenshot({ path: `${OUT}/fs-sm-waypoints.png`, fullPage: true });
  await page.close();
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

