// Open an FS image group; report image count; jump to image N; screenshot
// usage: node fsimg.js <owc-url> <startImg> <endImg> <prefix>
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';

const url = process.argv[2];
const from = parseInt(process.argv[3] || '1');
const to = parseInt(process.argv[4] || '0');
const prefix = process.argv[5] || 'fsimg';

(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 200 });
  const ctx = browser.contexts()[0];
  const page = await ctx.newPage();
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  for (let i = 1; i <= 14; i++) { await sleep(4000); const l = await page.evaluate(() => document.body.innerText.length).catch(() => 0); if (l > 1000) break; }
  await sleep(3000);
  const t = await page.evaluate(() => document.body.innerText);
  console.log('TITLE:', await page.title());
  console.log('HEAD:', t.slice(0, 600).replace(/\n+/g, ' | '));
  // count: "Image 1 of N" or grid
  const m = t.match(/Image\s+\d+\s+of\s+(\d+)/i);
  console.log('TOTAL IMAGES:', m ? m[1] : 'unknown');
  await page.screenshot({ path: `${OUT}/${prefix}-landing.png`, fullPage: true });
  fs.writeFileSync(`${OUT}/${prefix}-landing.txt`, t);
  await page.close();
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 300)); process.exit(1); });

