const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 100 });
  const ctx = browser.contexts()[0];
  const page = ctx.pages().find(p => /antenati/.test(p.url())) || await ctx.newPage();
  if (!/antenati/.test(page.url())) { await page.goto('https://antenati.cultura.gov.it/', { waitUntil: 'load', timeout: 60000 }); await sleep(4000); }
  const r = await page.evaluate(async () => {
    const res = await fetch('https://dam-antenati.cultura.gov.it/antenati/containers/0Mnvjl3/manifest', { credentials: 'include' });
    const j = await res.json();
    return { status: res.status, canvases: j.sequences ? j.sequences[0].canvases.length : null };
  });
  console.log(JSON.stringify(r));
  async function sleep(ms) { return new Promise(r2 => setTimeout(r2, ms)); }
  await browser.close();
})().catch(e => { console.error('E', e.message.slice(0, 150)); });
" 2>&1

