// Open ark in EXISTING antenati tab (no new tabs), walk ALL pages, screenshot each valid one
// usage: node idxwalk.js <ark> <prefix>
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
const ark = process.argv[2];
const prefix = process.argv[3];
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 120 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /antenati/.test(p.url()));
  if (!page) { page = await ctx.newPage(); }
  await page.goto(`https://antenati.cultura.gov.it/ark:/12657/${ark}`, { waitUntil: 'load', timeout: 60000 });
  await sleep(10000);
  await page.bringToFront();
  const total = await page.evaluate(() => {
    const m = document.body.innerText.match(/(\d+) di (\d+)/);
    return m ? parseInt(m[2]) : 0;
  });
  console.log(`${prefix}: ${total} pages`);
  if (!total) { await browser.close(); process.exit(2); }
  const shotValid = f => { try { return fs.statSync(f).size > 250000; } catch (e) { return false; } };
  let blanks = 0;
  for (let p = 1; p <= total; p++) {
    const f = `${OUT}/${prefix}-p${String(p).padStart(2, '0')}.png`;
    if (shotValid(f)) { console.log(`p${p} cached`); continue; }
    // ensure on page p
    let cur = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[1]) : 0; });
    let guard = 0;
    while (cur !== p && guard < 40) {
      await page.evaluate(({ target }) => {
        const okBtn = [...document.querySelectorAll('button')].find(x => /^ok$/i.test((x.innerText || '').trim()));
        if (okBtn) { okBtn.click(); return; }
        const m = document.body.innerText.match(/(\d+) di (\d+)/);
        const c = m ? parseInt(m[1]) : 0;
        const next = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        const prev = [...document.querySelectorAll('button')].find(x => /previous item/i.test(x.title || ''));
        if (c < target && next) next.click();
        else if (c > target && prev) prev.click();
      }, { target: p });
      await sleep(3200);
      cur = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[1]) : 0; });
      guard++;
    }
    await sleep(6500);
    await page.screenshot({ path: f });
    let ok = shotValid(f), tries = 0;
    while (!ok && tries < 6) {
      tries++;
      console.log(`p${p} throttled, wait 30s (${tries})`);
      await sleep(30000);
      await page.screenshot({ path: f });
      ok = shotValid(f);
    }
    if (!ok) { blanks++; console.log(`p${p} BLANK after retries - stopping (CDN re-block)`); break; }
    console.log(`p${p} ok`);
    await sleep(8000);
  }
  console.log('DONE, blanks:', blanks);
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 200)); process.exit(1); });

