// Jump directly to specific pages of an Antenati register and screenshot
// usage: node idxjump.js <ark> <prefix> <p1,p2,p3...>
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
const ark = process.argv[2];
const prefix = process.argv[3];
const pages = process.argv[4].split(',').map(Number);
(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 120 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /antenati/.test(p.url()));
  if (!page) page = await ctx.newPage();
  await page.goto(`https://antenati.cultura.gov.it/ark:/12657/${ark}`, { waitUntil: 'load', timeout: 60000 });
  await sleep(11000);
  await page.bringToFront();
  let total = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[2]) : 0; });
  console.log(`${prefix}: ${total} pages, targets: ${pages.join(',')}`);
  if (!total) { console.log('NO PAGER (CDN block?)'); await browser.close(); process.exit(2); }
  const shotValid = f => { try { return fs.statSync(f).size > 250000; } catch (e) { return false; } };

  for (const p of pages) {
    if (p > total) { console.log(`p${p} > total ${total}, skip`); continue; }
    const f = `${OUT}/${prefix}-p${String(p).padStart(2, '0')}.png`;
    if (shotValid(f)) { console.log(`p${p} cached`); continue; }
    // navigate to page p
    let cur = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[1]) : 0; });
    let guard = 0;
    while (cur !== p && guard < 45) {
      await page.evaluate(({ target }) => {
        const okBtn = [...document.querySelectorAll('button')].find(x => /^ok$/i.test((x.innerText || '').trim()));
        if (okBtn) { okBtn.click(); return; }
        const m = document.body.innerText.match(/(\d+) di (\d+)/);
        const c = m ? parseInt(m[1]) : 0;
        const next = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
        const prev = [...document.querySelectorAll('button')].find(x => /previous item/i.test(x.title || ''));
        if (c < target && next) next.click();
        else if (c > target && prev) prev.click();
      }, { target: p });
      await sleep(3000);
      cur = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[1]) : 0; });
      guard++;
    }
    await sleep(7000);
    await page.screenshot({ path: f });
    let ok = shotValid(f), tries = 0;
    while (!ok && tries < 4) {
      tries++;
      console.log(`p${p} blank, wait 35s (${tries})`);
      await sleep(35000);
      await page.screenshot({ path: f });
      ok = shotValid(f);
    }
    if (!ok) { console.log(`p${p} BLANK - stopping`); break; }
    console.log(`p${p} ok`);
    await sleep(9000);
  }
  console.log('DONE');
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 200)); process.exit(1); });

// Wait for CDN window, then grab T-section pages of ALL marriage indices 1866-1871 in one window
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
const fs = require('fs');
const sleep = ms => new Promise(r => setTimeout(r, ms));
const OUT = '/tmp/nas_takeover/fsbot/out';
const shotValid = f => { try { return fs.statSync(f).size > 250000; } catch (e) { return false; } };

const REGS = [
  { ark: 'an_ua2053593', prefix: 'matidx1866', pages: [6, 7, 8, 9, 10] },
  { ark: 'an_ua2053596', prefix: 'matidx1867', pages: [6, 7, 8, 9, 10] },
  { ark: 'an_ua2053597', prefix: 'matidx1868', pages: [6, 7, 8, 9, 10] },
  { ark: 'an_ua2053600', prefix: 'matidx1869', pages: [6, 7, 8, 9, 10] },
  { ark: 'an_ua2053602', prefix: 'matidx1870', pages: [6, 7, 8, 9, 10] },
  { ark: 'an_ua2053605', prefix: 'matidx1871', pages: [6, 7, 8, 9, 10] },
];

(async () => {
  const browser = await chromium.connectOverCDP('http://127.0.0.1:9222', { slowMo: 100 });
  const ctx = browser.contexts()[0];
  let page = ctx.pages().find(p => /antenati/.test(p.url()));
  if (!page) page = await ctx.newPage();

  const need = () => REGS.filter(r => r.pages.some(p => !shotValid(`${OUT}/${r.prefix}-p${String(p).padStart(2, '0')}.png`)));
  let windowUses = 0;
  let round = 0;

  while (need().length && round < 40) {
    round++;
    // probe: is the window open? try the first missing page
    const reg = need()[0];
    const missingPage = reg.pages.find(p => !shotValid(`${OUT}/${reg.prefix}-p${String(p).padStart(2, '0')}.png`));
    console.log(`[round ${round}] probing ${reg.prefix} p${missingPage}`);
    try {
      await page.goto(`https://antenati.cultura.gov.it/ark:/12657/${reg.ark}`, { waitUntil: 'load', timeout: 60000 });
      await sleep(9000);
      const total = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[2]) : 0; });
      if (!total) { console.log('manifest blocked, wait 10min'); await sleep(600000); continue; }
      // window is OPEN - grab everything we can from THIS register first
      for (const p of reg.pages) {
        const f = `${OUT}/${reg.prefix}-p${String(p).padStart(2, '0')}.png`;
        if (shotValid(f) || p > total) continue;
        let cur = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[1]) : 0; });
        let guard = 0;
        while (cur !== p && guard < 40) {
          await page.evaluate(({ target }) => {
            const okBtn = [...document.querySelectorAll('button')].find(x => /^ok$/i.test((x.innerText || '').trim()));
            if (okBtn) { okBtn.click(); return; }
            const m = document.body.innerText.match(/(\d+) di (\d+)/);
            const c = m ? parseInt(m[1]) : 0;
            const next = [...document.querySelectorAll('button')].find(x => /prossimo oggetto/i.test(x.title || ''));
            const prev = [...document.querySelectorAll('button')].find(x => /previous item/i.test(x.title || ''));
            if (c < target && next) next.click(); else if (c > target && prev) prev.click();
          }, { target: p });
          await sleep(2600);
          cur = await page.evaluate(() => { const m = document.body.innerText.match(/(\d+) di (\d+)/); return m ? parseInt(m[1]) : 0; });
          guard++;
        }
        await sleep(6000);
        await page.screenshot({ path: f });
        if (shotValid(f)) { console.log(`  ${reg.prefix} p${p} OK`); windowUses++; await sleep(6000); }
        else {
          console.log(`  ${reg.prefix} p${p} blank - window closing, wait 10min`);
          windowUses = 99; // force window reset
          break;
        }
        if (windowUses >= 6) { console.log('window budget spent, wait 10min'); windowUses = 0; await sleep(600000); break; }
      }
    } catch (e) {
      console.log('ERR', e.message.slice(0, 100), '- wait 10min');
      await sleep(600000);
    }
  }
  console.log('ALL DONE or exhausted');
  await browser.close();
})().catch(e => { console.error('FATAL', e.message.slice(0, 200)); process.exit(1); });

