# Extract just the register content from the full-res PNG using sharp-style cropping via canvas in headless chrome
node -e "
const { chromium } = require('/tmp/nas_takeover/fsbot/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await (await browser.newContext({ viewport: { width: 1200, height: 800 } })).newPage();
  const fs = require('fs');
  const img = fs.readFileSync('/tmp/nas_takeover/fsbot/out/matidx1871-p04.png').toString('base64');
  await page.setContent('<html><body style=\"margin:0\"><canvas id=\"c\"></canvas></body></html>');
  const crop = await page.evaluate(async (b64) => {
    const img = new Image();
    img.src = 'data:image/png;base64,' + b64;
    await new Promise(r => img.onload = r);
    // crop: x 1100-2348, y 700-2100 (the right page content with names)
    const cw = 1248, ch = 1400;
    const c = document.getElementById('c');
    c.width = cw; c.height = ch;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 1100, 700, cw, ch, 0, 0, cw, ch);
    return c.toDataURL('image/png');
  }, img);
  fs.writeFileSync('/tmp/nas_takeover/fsbot/out/mi71-p04-content.png', Buffer.from(crop.split(',')[1], 'base64'));
  console.log('cropped p04');
  await browser.close();
})();
